    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the sequence {a_n} of positive real numbers with a_1={initial_a1} and a_2={initial_a2}. It satisfies, for all positive integers n, the disguised fourth-power linear recurrence\n8({l_scale}a_{n+2}+{m_shift})^4=3+4({l_scale}a_{n+1}+{m_shift})+({l_scale}a_n+{m_shift}).\nFind a closed-form expression for a_n in terms of n. After solving, output your final answer exactly in the format:\n### The final answer is: $\\boxed{<your answer>}$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters L, M and initial b1 so that the transformed sequence b_n := L a_n + M
# satisfies the seed recurrence 8 b_{n+2}^4 = 3 + 4 b_{n+1} + b_n with the crucial base relation
# 2 b_2^2 = 1 + b_1. Then we back-transform to a_n.
while True:
    L = rng.randint(2, 6)        # scaling; L>=2 to ensure nontrivial disguise
    M = rng.choice([0, 1])       # small shift to preserve positivity and still disguise
    b1 = rng.randint(4, 20)      # ensure b1>1 for arcosh to be defined and sequence positivity
    b2 = ((1 + b1) / 2.0) ** 0.5 # enforce base relation 2 b2^2 = 1 + b1
    # Back-transform to a's: b_k = L a_k + M
    a1 = (b1 - M) / float(L)
    a2 = (b2 - M) / float(L)
    # Validate positivity and nontriviality
    if a1 > 0 and a2 > 0:
        # Construct assignment
        assign = {
            'l_scale': L,
            'm_shift': M,
            'initial_a1': a1,
            'initial_a2': a2
        }
        return assign
# Fallback (should never reach)
return {'l_scale': 2, 'm_shift': 0, 'initial_a1': 3.5, 'initial_a2': ((1+7)/2.0)**0.5/2.0}

    def verifier(assign):
# Verify domain constraints and compute the closed form answer.
# Return (True, answer) on success; (False, None) on failure.
try:
    L = assign.get('l_scale', None)
    M = assign.get('m_shift', None)
    a1 = assign.get('initial_a1', None)
    a2 = assign.get('initial_a2', None)
    # Basic type/domain checks
    if not isinstance(L, int) or not isinstance(M, int):
        # invalid types
        return (False, None)  # types must be ints
    if L < 2 or M < 0:
        # enforce nontrivial disguise and nonnegative shift
        return (False, None)
    if not (isinstance(a1, (int, float)) and isinstance(a2, (int, float))):
        return (False, None)
    if not (a1 > 0 and a2 > 0):
        return (False, None)
    # Check the crucial base relation in the disguised variables b_n = L a_n + M:
    b1 = L * a1 + M
    b2 = L * a2 + M
    # arcosh is defined only for b1 >= 1; we enforce b1 > 1 for increasing sequence positivity.
    if not (b1 > 1):
        return (False, None)
    # Verify 2 b2^2 = 1 + b1 (within numerical tolerance due to floating arithmetic)
    lhs = 2.0 * (b2 ** 2)
    rhs = 1.0 + b1
    if abs(lhs - rhs) > 1e-9:
        # Not consistent with the intended family; reject.
        return (False, None)
    # Construct the closed form using the hyperbolic cosine duplication:
    # b_n = cosh( arcosh(b1) / 2^{n-1} ), so a_n = (b_n - M)/L.
    # Build the LaTeX string for the final answer.
    # We keep b1 numeric to avoid hidden parameters in the wrapper.
    # Final answer must contain n.
    # Use cosh/arcosh to express cleanly.
    # Format: (cosh( arcosh(b1) / 2^{n-1} ) - M)/L
    # Include small spacing consistent with LaTeX best practice.
    def fmt_num(x):
        # Robust formatting for integers or floats
        if isinstance(x, int):
            return str(x)
        # format floats to 10 significant digits to avoid noisy tails
        return ("%0.10g" % x)
    b1_str = fmt_num(b1)
    M_str = fmt_num(M)
    L_str = fmt_num(L)
    answer = "\\frac{\\cosh\\!\\left(\\frac{\\mathrm{arcosh}\," + b1_str + "}{2^{n-1}}\\right) - " + M_str + "}{" + L_str + "}"
    return (True, answer)
except Exception:
    # Any unexpected error: reject with explanation disabled by API contract
    return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

